ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Document" ADD CONSTRAINT "Document_createdById_fkey" FOREIGN KEY("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "DocumentVersion" ADD CONSTRAINT "DocumentVersion_documentId_fkey" FOREIGN KEY("documentId") REFERENCES "Document"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Attachment" ADD CONSTRAINT "Attachment_uploadedById_fkey" FOREIGN KEY("uploadedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Attachment" ADD CONSTRAINT "Attachment_documentId_fkey" FOREIGN KEY("documentId") REFERENCES "Document"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EpiAssignment" ADD CONSTRAINT "EpiAssignment_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EpiAssignment" ADD CONSTRAINT "EpiAssignment_epiId_fkey" FOREIGN KEY("epiId") REFERENCES "Epi"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EpiMovement" ADD CONSTRAINT "EpiMovement_epiId_fkey" FOREIGN KEY("epiId") REFERENCES "Epi"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EpiMovement" ADD CONSTRAINT "EpiMovement_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "EpiMovement" ADD CONSTRAINT "EpiMovement_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QualityControl" ADD CONSTRAINT "QualityControl_createdById_fkey" FOREIGN KEY("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QualityControl" ADD CONSTRAINT "QualityControl_templateId_fkey" FOREIGN KEY("templateId") REFERENCES "ControlTemplate"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ControlPoint" ADD CONSTRAINT "ControlPoint_templateId_fkey" FOREIGN KEY("templateId") REFERENCES "ControlTemplate"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ControlResult" ADD CONSTRAINT "ControlResult_controlId_fkey" FOREIGN KEY("controlId") REFERENCES "QualityControl"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ControlResult" ADD CONSTRAINT "ControlResult_pointId_fkey" FOREIGN KEY("pointId") REFERENCES "ControlPoint"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ControlResult" ADD CONSTRAINT "ControlResult_createdById_fkey" FOREIGN KEY("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "NonConformity" ADD CONSTRAINT "NonConformity_qualityControlId_fkey" FOREIGN KEY("qualityControlId") REFERENCES "QualityControl"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Action" ADD CONSTRAINT "Action_responsibleId_fkey" FOREIGN KEY("responsibleId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Action" ADD CONSTRAINT "Action_nonConformityId_fkey" FOREIGN KEY("nonConformityId") REFERENCES "NonConformity"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QhseAudit" ADD CONSTRAINT "QhseAudit_auditorId_fkey" FOREIGN KEY("auditorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
